-- Add every fact from the supplied eighth Lily collection. One obsolete label is
-- replaced with neutral wording while retaining the source's historical meaning.
-- Russian/Russia content is soft-hidden with isActive rather than deleted.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (679, $$Сюжет фильма «Гладиатор» (2000): История Максимуса — это не просто выдумка сценаристов, а прямая компиляция трудов историков Геродиана и Элия Лампридия [nplus1.ru]. Образ безумного императора Коммода, сражающегося на арене, и заговор его сестры Люциллы детально описаны в античных хрониках.$$),
  (680, $$«Матрица» Вачовски: Концепция мира-иллюзии, где люди видят лишь тени реальных вещей, — это буквальная визуализация «Мифа о пещере» Платона из VII книги трактата «Государство». Философ еще 2400 лет назад описал узников, прикованных лицом к стене, принимающих тени за истинную реальность.$$),
  (681, $$Структура детективов об Агате Кристи: Метод Эркюля Пуаро собирать всех подозреваемых в одной комнате в финале для разоблачения убийцы скопирован с судебных речей Лисия (IV в. до н.э.), который в речи «Об убийстве Эратосфена» выстраивал повествование как поэтапное раскрытие семейных тайн перед судьями.$$),
  (682, $$Сюжет «Дракулы» Брэма Стокера: Сцена, где Джонатан Харкер приезжает в замок и сталкивается с призрачными явлениями, повторяет классический античный рассказ ужасов Плиния Младшего о доме с привидениями в Афинах, где дух закованного в цепи старика указывал на место своего захоронения.$$),
  (683, $$Фильм «Начало» (Inception) Нолана: Идея многоуровневых снов, где время течет с разной скоростью, заложена в трудах Макробия «Комментарий на сон Сципиона» (V в. н.э.), где детально классифицировались типы сновидений и их глубина.$$),
  (684, $$Роман «Повелитель мух» Уильяма Голдинга: История о детях, одичавших на острове, построена как зеркальное опровержение «Киропедии» Ксенофонта, который доказывал, что благородная природа человека и правильное воспитание удерживают общество от деградации даже в экстремальных условиях.$$),
  (685, $$Сюжет «Аватара» Джеймса Кэмерона: Сюжет о солдате, который внедряется в племя коренных жителей, проникается их культурой и возглавляет их восстание, полностью повторяет историю Арминия, описанную Тацитом: германский вождь служил в римской армии, изучил их тактику, а затем уничтожил легионы Вара в Тевтобургском лесу.$$),
  (686, $$«Французский вестник» Уэса Андерсона: Структура фильма, состоящего из новелл-репортажей, вдохновлена жанром пестрых рассказов (Varia historia) Элиана (III в. н.э.), который собирал забавные анекдоты о животных, странных обычаях и безумствах художников.$$),
  (687, $$Сериал «Во все тяжкие» (Breaking Bad): Архетип скромного учителя, который под давлением обстоятельств превращается в жестокого криминального босса, соответствует психологическому перерождению царя Эдипа в трагедии Сенеки «Эдип», где герой постепенно осознает свою темную судьбу и принимает её.$$),
  (688, $$Фильм «Шоу Трумана»: Идея искусственного мира, созданного для развлечения одного человека, является парафразом философского мифа Лукиана Самосатского из диалога «Икароменипп», где боги смотрят на Землю через специальные люки как на гигантский кукольный театр.$$),
  (689, $$Синдром Стендаля в античности: Первое литературное описание обморока и шока от созерцания невероятной красоты (физической или художественной) зафиксировано в поэзии Сапфо, которая описывала, как при виде возлюбленной у неё «гаснет взор и бледнеет кожа».$$),
  (690, $$Психология толпы: Французский социолог Гюстав Лебон при создании книги «Психология народов и масс» опирался на «Историю» Ливия, который детально описал, как римская толпа мгновенно превращается из трусливого сборища в яростную карающую силу под влиянием одного слуха.$$),
  (691, $$Эффект ложного воспоминания: В трагедии Софокла «Электра» подробно описан феномен того, как человек может искренне горевать над вымышленным событием: Электра оплакивает урну с прахом брата Ореста, веря ложной ведомости о его гибели, что запускает глубокий психосоматический кризис.$$),
  (692, $$Кризис среднего возраста: Первое структурированное описание экзистенциального тупика 40-летнего человека дано в «Диалогах» Сенеки («О скоротечности жизни»), где он критикует людей, откладывающих истинную жизнь на старость.$$),
  (693, $$Психология посттравматического синдрома (ПТСР): Образ безумного Геракла в трагедии Еврипида «Неистовствующий Геракл» — это точнейшее описание боевой психической травмы воина, который, вернувшись с войны, в припадке галлюцинаций уничтожает собственную семью.$$),
  (694, $$Феномен проекции: Философ Ксенофан (VI в. до н.э.) первым описал механизм психологической проекции, заметив, что люди создают богов по своему образу и подобию: «Если бы быки и львы имели руки и умели рисовать, они нарисовали бы богов быками и львами».$$),
  (695, $$Анатомия зависти: Плутарх в трактате «О зависти и ненависти» первым разделил эти два чувства, доказав, что ненависть направлена на врагов, а зависть — исключительно на близких и успешных друзей.$$),
  (696, $$Эффект Пигмалиона: Психологический феномен, когда ожидания человека определяют реальность, получил название из X книги «Метаморфоз» Овидия, где скульптор Пигмалион так сильно верил в совершенство созданной им статуи Галатеи, что боги оживили её.$$),
  (697, $$Теория сновидений: Артемидор Далдианский во II веке н.э. написал «Онейрокритику» — первый в истории пятитомный сонник, который Зигмунд Фрейд признал главным предком своей книги «Толкование сновидений» за попытку связать сны с дневными тревогами человека.$$),
  (698, $$Психология тирании: Трактат Ксенофонта «Гиерон» — это глубокий психологический диалог между поэтом и тираном, где последний признается, что богатство и власть лишают его главного человеческого счастья — возможности иметь искренних, бескорыстных друзей.$$),
  (699, $$Слово «Педиатрия»: Корни термина восходят к греческому слову Pais (ребенок) и Iatreia (лечение), которые впервые были соединены в медицинских трактатах Гиппократовского корпуса.$$),
  (700, $$Происхождение слова «Гений»: В римской литературе Genius — это не человек с высоким IQ, а личный дух-хранитель, рождающийся вместе с мужчиной. Наша привычка говорить «он гений» вместо «в нем говорит гений» — это языковая трансформация Нового времени.$$),
  (701, $$Слово «Стиль»: Происходит от латинского Stilus — острая палочка для письма на восковых дощечках. Римские риторы советовали «чаще переворачивать стиль» (стирать написанное тупым концом), что превратило технический термин в синоним качественного текста.$$),
  (702, $$Слово «Сарказм»: Происходит от греческого глагола Sarkazo, что буквально означает «рвать мясо как собака». В античную риторику термин вошел как обозначение самой злой, язвительной насмешки, ранящей оппонента.$$),
  (703, $$Термин «Катастрофа»: В древнегреческом театре Katastrophe означало всего лишь «поворот сюжета» или «развязку трагедии». Разрушительный природный или социальный смысл слово обрело гораздо позже.$$),
  (704, $$Слово «Паллиатив»: Происходит от латинского Pallium — свободный римский плащ, которым укутывались поверх одежды. В литературе Нового времени слово стало означать «прикрытие проблемы», а затем перешло в медицину как лечение, облегчающее симптомы, но не устраняющее болезнь.$$),
  (705, $$Происхождение слова «Экстаз»: Древнегреческий термин Ekstasis буквально означал «выход из себя» или «смещение со своего места». В трагедиях Еврипида так описывалось состояние безумия жриц-вакханок.$$),
  (706, $$Слово «Симпозиум»: Сегодня это серьезная научная конференция, но в переводах трактатов Платона и Ксенофонта Symposion переводится буквально как «совместное пиршество/совозлияние» — интеллектуальная беседа, сопровождавшаяся умеренным распитием вина.$$),
  (707, $$Термин «Ностальгия»: Составлен швейцарским врачом в XVII веке из двух античных слов: Nostos (возвращение домой — главный мотив «Одиссеи») и Algos (боль, страдание), чтобы описать тоску солдат по родине.$$),
  (708, $$Слово «Идиот»: В древнегреческой политической литературе (например, у Фукидида) Idiotes — это не человек с ментальными нарушениями, а гражданин, который сознательно игнорирует участие в политической и общественной жизни полиса, живя исключительно частными интересами.$$),
  (709, $$Великая кража книг: Птолемей III Эвергет выпросил у Афин оригиналы государственных рукописей Эсхила, Софокла и Еврипида под огромный залог в 15 талантов серебра. Получив книги, царь предпочел оставить серебро Афинам, а оригиналы забрал в Александрийскую библиотеку, вернув грекам лишь копии.$$),
  (710, $$«О природе вещей» Лукреция: Великая поэма, заложившая основы материализма, была полностью утеряна для Европы на протяжении Средних веков. В 1417 году гуманист Поджо Браччолини случайно обнаружил единственную уцелевшую копию в далеком немецком монастыре, что запустило интеллектуальный взлет Возрождения.$$),
  (711, $$Античные подделки: Римский поэт Федр (I в. н.э.) жаловался, что вынужден подписывать свои басни именем Эзопа, так как римские издатели отказывались покупать тексты современных авторов, требуя исключительно «авторитетные древние имена».$$),
  (712, $$Папирусы Оксиринха: На мусорных свалках древнего египетского города Оксиринха археологи нашли сотни тысяч обрывков рукописей. Благодаря этой «мусорке» мир вернул утерянные комедии Менандра и стихи Сапфо, которые считались утраченными навсегда.$$),
  (713, $$Пожар в библиотеке Писсона: На вилле в Геркулануме была найдена единственная уцелевшая библиотека античности. Свитки обуглились при извержении Везувия, превратившись в древесный уголь. Сегодня ученые читают их с помощью искусственного интеллекта, определяющего плотность свинцовых чернил внутри сожженного папируса.$$),
  (714, $$«Анналы» Тацита: Первая-шестая книги главного исторического труда Рима сохранились в одном-единственном экземпляре в монастыре Корвей. Если бы этот манускрипт сгорел, мы бы ничего не знали о деталях правления императора Тиберия.$$),
  (715, $$Формат Кодекса: Переход от длинных папирусных свитков к сшитым листам с обложкой (кодексам — прообразам современных книг) произошел в I веке н.э. Римский поэт Марциал первым рекламировал этот формат, объясняя, что такую книгу удобно держать одной рукой в дороге.$$),
  (716, $$Заводное книгоиздание Рима: Крупные издатели (например, Аттик, друг Цицерона) имели штаты из сотен грамотных рабов-переписчиков. Один чтец диктовал текст, а сто рабов одновременно записывали его, что позволяло выпускать тиражи книг за один день.$$),
  (717, $$Утерянная половина Аристотеля: Наша «Поэтика» Аристотеля состоит только из первой части (анализ трагедии и эпоса). Вторая часть, посвященная анализу комедии и смеха, была полностью утеряна в раннем Средневековье, что легло в основу сюжета романа Умберто Эко «Имя розы».$$),
  (718, $$Манускрипт Войнича и античный след: Некоторые лингвисты предполагают, что шифр загадочной рукописи XV века базируется на анаграммах латинских текстов римского агронома Колумеллы, зашифрованных для сокрытия алхимических рецептов.$$),
  (719, $$Рождение жанра «Сладкая горечь»: Сапфо первой ввела в мировую литературу оксюморон «горько-сладкая любовь» (Glukupikron), описав амбивалентную природу страсти, которая одновременно дарит высшее блаженство и причиняет боль.$$),
  (720, $$«Наука любви» Овидия как запрещенное оружие: Эта поэма, обучающая мужчин и женщин методам флирта, тайной переписки и соблазнения, настолько возмутила императора Августа, проводившего консервативную реформу морали, что книга была изъята из общественных библиотек, а автора сослали в ссылку.$$),
  (721, $$Образ идеального друга-напарника: Гомер в «Илиаде» через отношения Ахилла и Патрокла создал вечный литературный канон верной мужской дружбы, где гибель напарника запускает главную разрушительную ярость героя (этот паттерн работает во всех современных боевиках).$$),
  (722, $$Первый психологический роман: «Дафнис и Хлоя» Лонга (II в. н.э.) — это первое в истории детальное описание зарождения пубертатного чувства у подростков, которые не понимают, что с ними происходит, принимая любовь за физическую болезнь.$$),
  (723, $$Элегии Катулла к Лесбии: Сборник стихов Катулла, посвященный его возлюбленной Клодии (выведенной под именем Лесбии), стал первым в истории реалистичным дневником разрушения отношений: от бурной страсти до ревности, взаимных оскорблений и полного разочарования.$$),
  (724, $$Концепция половинок (Андрогины): Миф о том, что боги изначально создали людей четырехрукими и четырехногими, а затем разрезали пополам, обрекая нас всю жизнь искать свою «вторую половинку», впервые рассказан Платоном в трактате «Пир» от лица драматурга Аристофана.$$),
  (725, $$Жанр «Утешение» (Consolatio): Сенека в письмах к матери Гельвии и Марции создал уникальный жанр терапевтической прозы, помогающий пережить смерть близких людей через логический анализ неизбежности рока.$$),
  (726, $$Метафора «Стрелы Амура»: Образ бога любви, стреляющего из лука золотыми стрелами (вызывающими любовь) и свинцовыми (вызывающими отвращение), был детально разработан Овидием в первой книге «Метаморфоз» (миф об Аполлоне и Дафне).$$),
  (727, $$Культ верности (Пенелопа): Образ Пенелопы, которая 20 лет ждет Одиссея, обманывая женихов вязанием и распусканием погребального савана, закрепил в мировой литературе эталон верности, ставший основой средневековых рыцарских романов.$$),
  (728, $$Поэтизация быта: Римский поэт Гораций в своих «Сатирах» первым доказал, что объектом высокой поэзии может быть не только подвиг героя, но и невкусный обед у скупого хозяина, давка в римской толпе или поездка в скрипучей телеге.$$),
  (729, $$«Памятник» Державина и Пушкина: Строка Пушкина «Я памятник себе воздвиг нерукотворный...» и стихотворение Державина — это прямые поэтические переводы и адаптации Оды XXX Горация (Exegi monumentum). Пушкин сохранил даже структуру и метрику римского стиха.$$),
  (730, $$«Герой нашего времени» Лермонтова: Образ Печорина и структура его дневника построены по канонам психологических элегий Овидия и «Исповеди» Святого Августина (который писал на латыни по лекалам римской риторики).$$),
  (731, $$«Горе от ума» Грибоедова: Чацкий является классическим типом античного мизантропа, списанного с комедий Менандра и пьесы Мольера, которая, в свою очередь, базировалась на римском театре Плавта.$$),
  (732, $$«Слово о полку Игореве»: Филологические исследования доказали, что автор «Слова» был знаком с византийскими переводами «Илиады» Гомера. Плач Ярославны на стене Путивля по своей поэтической структуре совпадает с плачем Андромахи на стенах Трои.$$),
  (733, $$«Шинель» Гоголя: Образ маленького человека Акакия Акакиевича и его сакральной вещи (шинели) использует сатирические приемы Теофраста из его книги «Характеры» (глава «Мелочность» и «Скупость»).$$),
  (734, $$«Анна Каренина» Толстого: Эпиграф к роману «Мне отмщение, и Аз воздам» отсылает к библейскому тексту, но драматическая структура гибели женщины, нарушившей законы общества ради страсти, полностью повторяет трагедию Еврипида «Ипполит» (история Федры).$$),
  (735, $$Поэзия Иосифа Бродского: Бродский был глубоким исследователем античности. Его циклы «Письма римскому другу» и «Постскриптум» — это прямая стилизация под поэмы Марциала и Проперция, перенесенная на контекст советской империи.$$),
  (736, $$«Бесы» Достоевского: Название романа и его эпиграф взяты из Евангелия, но логика политического заговора Петра Верховенского полностью копирует исторические хроники Саллюстия «О заговоре Катилины», описывающие методы разрушения государства изнутри.$$),
  (737, $$«Борис Годунов» Пушкина: Образ Пимена-летописца, бесстрастно записывающего грехи царей, создан Пушкиным под влиянием чтения «Анналов» Тацита, которого поэт называл «бичом тиранов».$$),
  (738, $$«Кому на Руси жить хорошо» Некрасова: Поэма-путешествие в поисках счастливого человека использует фольклорно-эпическую структуру «Одиссеи», перенесенную на крестьянский быт пореформенной России.$$),
  (739, $$Супермен и криптонит: Идея о том, что неуязвимый супергерой теряет все силы при приближении к осколкам своей родной планеты, — это адаптация мифа об Антее, великане, который был непобедим, пока касался матери-Земли, но потерял силу, когда Геракл оторвал его от почвы.$$),
  (740, $$Оборотни в хоррорах: Первое детальное описание ликантропии (превращения человека в волка) дано в романе Петрония «Сатирикон» (рассказ вольноотпущенника Ницерота о солдате, который на кладбище разделся, превратился в волка и убежал в лес резать скот).$$),
  (741, $$«Хроники Нарнии» К.С. Льюиса: Образы кентавров, фавнов, дриад и самой Белой Колдуньи полностью взяты писателем (который был профессором средневековой и античной литературы в Оксфорде) из «Метаморфоз» Овидия и «Теогонии» Гесиода.$$),
  (742, $$«Франкенштейн» Мэри Шелли: Оригинальный метод оживления плоти с помощью электричества и тайных наук вдохновлен описанием ведьмы Эрихто в VI книге поэмы Лукана «Фарсалия», где она с помощью заклинаний и зелий оживляет труп солдата для предсказания будущего.$$),
  (743, $$Комиксы о Торе и Локи: Сценаристы Marvel выстроили динамику отношений братьев (благородный воин и хитрый трикстер) по лекалам комедии Плавта «Амфитрион», где Меркурий и Юпитер постоянно разыгрывают смертных, меняя внешность.$$),
  (744, $$Вселенная «Дюны» Фрэнка Герберта: Высший орден женщин Бене Гессерит, управляющий генетическими линиями человечества и политикой империй, списан с института римских весталок и описаний пророчиц-Сивилл в античной литературе.$$),
  (745, $$«Гарри Поттер» и заклинания: Все вербальные заклинания в мире Роулинг (Экспеллиармус, Авада Кедавра, Люмос) — это измененные латинские формулы, взятые из римских медицинских и магических трактатов Плиния Старшего.$$),
  (746, $$Образ Зомби в хоррорах: Наше представление о восставших мертвецах, которые бродят толпами, заложено в «Диалогах» греческого сатирика Лукиана, который высмеивал суеверия современников, веривших в некромантию — вызов мертвецов с сохранением их разлагающихся тел.$$),
  (747, $$Киберпанк Уильяма Гибсона: Концепция корпораций, которые стоят выше закона и имеют собственные армии, — это проекция истории Первого триумвирата (Цезарь, Помпей, Красс), описанной Плутархом, когда три богатейших человека фактически приватизировали Римскую республику.$$),
  (748, $$«Властелин колец» и Кольцо Всевластья: Идея кольца, которое делает владельца невидимым, но развращает его душу, полностью взята Толкином из II книги трактата Платона «Государство» («Миф о кольце Гига»).$$),
  (749, $$Система школьных оценок: Идея оценивать успехи учеников по баллам или категориям зародилась в римских риторических школах Квинтилиана, который ввел ранжирование учеников по качеству их речей для стимулирования духа соперничества (aemulatio).$$),
  (750, $$Иллюстрированная детская книга: Прообразы учебников с картинками для детей появились в Александрии, где рукописи басен Эзопа снабжались яркими рисунками на полях, чтобы помочь детям, только осваивающим чтение, соотносить слова с образами.$$),
  (751, $$Метод Сократа в современной педагогике: Метод обучения через наводящие вопросы, когда учитель не дает готовый ответ, а заставляет ученика самого прийти к истине, является основой прогрессивных систем образования (например, Вальдорфской школы).$$),
  (752, $$Басни Лафонтена и Крылова: 90% сюжетов классических басен, на которых воспитываются дети («Стрекоза и Муравей», «Ворона и Лисица»), — это прямые переложения поэм римского баснописца Федра и грека Бабрия (II в. н.э.).$$),
  (753, $$Формирование концепции «Хобби»: Само понятие развивающего досуга, не приносящего материальной выгоды, развилось из латинского концепта Otium cum dignitate («Отдых с достоинством»), детально описанного Цицероном как лучшее время для чтения и самоанализа.$$),
  (754, $$Детские сказки о животных (Антропоморфизм): Наша привычка наделять животных человеческими чертами (лиса — хитрая, волк — глупый) зафиксирована в античном трактате «О свойствах животных» Элиана, который стал базой для всех средневековых бестиариев.$$),
  (755, $$Школьная риторика: Приемы школьных сочинений на заданную тему (например, «Эссе-рассуждение») строятся по правилам прогимнасмаг — античных сборников упражнений по развитию письменной речи для подростков.$$),
  (756, $$Концепция гармоничного развития: Идея о том, что ребенок должен развивать одновременно и разум (литература, математика), и тело (спорт), была научно обоснована в трактате Аристотеля «Политика» как единственный способ вырастить свободного гражданина.$$),
  (757, $$Образ злой мачехи: Классический сказочный архетип злой мачехи, преследующей падчерицу («Золушка», «Белоснежка»), зародился в трагедиях Еврипида (в частности, в утерянной пьесе «Эгей»), где мачеха Медея пытается отравить пасынка Тесея.$$),
  (758, $$Университетские каникулы: Само слово «каникулы» происходит от латинского Dies caniculares («собачьи дни»). В римской литературе так называли самый жаркий период лета (с конца июля по август), когда созвездие Большого Пса (с яркой звездой Сириус — Каникулой) поднималось на небе, и занятия в школах прекращались из-за зноя.$$),
  (759, $$Защита от когнитивных искажений: Человек, изучивший трактат Аристотеля «О софистических опровержениях», получает абсолютную защиту от дешевых манипуляций в медиа, так как философ детально классифицировал все логические ошибки и уловки в спорах.$$),
  (760, $$Формирование сложного синтаксиса речи: Чтение речей Цицерона или исторических трудов Тацита развивает у человека способность строить длинные, логически безупречные предложения, что повышает интеллектуальный статус его речи в реальной жизни.$$),
  (761, $$Эстетическая независимость: Воспитание вкуса на поэзии Горация, Вергилия и Овидия создает внутренний фильтр, который делает человека невосприимчивым к низкокачественному массовому культурному продукту.$$),
  (762, $$Стоический иммунитет к стрессу: Постоянное чтение «Нравственных писем к Луцилию» Сенеки признано психологами лучшим инструментом для выстраивания психологических границ и сохранения хладнокровия в эпохи социальных кризисов.$$),
  (763, $$Понимание неизменности человеческой природы: Великие трагедии Софокла и Еврипида доказывают, что за 2500 лет природа человека (страсть, амбиции, страх, благородство) не изменилась ни на миллиметр. Это знание лишает иллюзий и дает глубокую экзистенциальную мудрость.$$),
  (764, $$Развитие здорового скептицизма: Сатиры Лукиана Самосатского учат критическому мышлению и тонкой иронии по отношению к любым фанатичным культам, суевериям и псевдонаучным теориям.$$),
  (765, $$Масштабное видение процессов: Античный исторический эпос приучает мозг мыслить категориями веков, государств и поколений, поднимая человека над мелкой повседневной суетой.$$),
  (766, $$Обретение внутренних этических ориентиров: Диалоги Сократа заставляют читателя лично ответить себе на вопросы: «Что есть благо?» и «Как прожить жизнь честно?», формируя несгибаемый внутренний моральный стержень.$$),
  (767, $$Литературная эрудиция как социальный лифт: Знание античных сюжетов и авторов — это до сих пор международный код интеллектуальной элиты, открывающий доступ к высокоранговым научным и культурным сообществам.$$),
  (768, $$Проживание опыта цивилизации: Читая античную библиотеку, вы за одну свою жизнь осваиваете ментальный опыт сотен умнейших людей человечества, получая колоссальное эволюционное преимущество в развитии собственного разума.$$),
  (769, $$Опечатка длиною в века: В некоторых средневековых списках «Георгик» Вергилия из-за невнимательности монаха-переписчика слово Apes (пчелы) было записано как Aves (птицы), что заставило целое поколение ученых Нового времени писать абсурдные трактаты о «пернатых пчелах» древности.$$),
  (770, $$Смерть от смеха: Античный философ и писатель Хрисипп умер от смеха, наблюдая, как его собственный осел ест инжир, после чего приказал рабу дать ослу выпить чистого вина, чтобы посмотреть, что будет дальше. Этот случай зафиксирован Диогеном Лаэртским.$$),
  (771, $$Посмертная воля Вергилия: Великий поэт перед смертью приказал сжечь незавершенную рукопись «Энеиды», считая её несовершенной. Император Октавиан Август лично нарушил волю автора, приказав издателям Варию и Тукке напечатать текст, удалив лишь явные грамматические ошибки, что спасло главный эпос Рима для человечества.$$),
  (772, $$Самый богатый писатель древности: Сенека благодаря своей писательской, философской и государственной деятельности (он был наставником Нерона) скопил колоссальное состояние в 300 миллионов сестерциев, став одним из богатейших людей империи, что вызывало жесткую критику современников, упрекавших его в лицемерии за проповедь стоической бедности.$$),
  (773, $$Псевдоним Гомера: В античной филологической литературе (в трактате «Состязание Гомера и Гесиода») утверждается, что настоящее имя Гомера было Мелесиген (рожденный у реки Мелес), а имя «Гомер» он получил позже, так как на ионийском диалекте это слово означало «слепец» или «заложник».$$),
  (774, $$Критика письменности от Платона: Парадокс заключается в том, что Платон записал миллионы слов своих диалогов, но в диалоге «Федр» от лица Сократа жестко критикует письменность, утверждая, что она убивает память человека и создает иллюзию знания вместо истинной мудрости.$$),
  (775, $$Первый литературный суд над критиком: Римский поэт Теренций (II в. до н.э.) превратил прологи к своим комедиям в настоящие судебные защитные речи, где он публично атаковал старого критика Луция Ланувина, обвинявшего его в плагиате и слабости стиля.$$),
  (776, $$Суеверия Плиния Старшего: Автор первой энциклопедии Плиний Старший погиб при извержении Везувия, так как подошел слишком близко ради научного интереса. Любопытно, что в своей «Естественной истории» он на полном серьезе зафиксировал рецепты от сглаза и инструкции по превращению свинца в золото.$$),
  (777, $$Поэтический шантаж Марциала: Римский эпиграммист Марциал открыто занимался литературным шантажом: он писал едкие сатирические стихи о пороках богачей, не называя имен, и патриции платили ему огромные деньги, чтобы он случайно не вывел их под узнаваемыми масками в своем следующем свитке.$$),
  (778, $$Ранний пример работы за автора: Римский поэт Ювенал в своих «Сатирах» высмеивал богатых патрициев, которые нанимали образованных греческих рабов для написания речей и стихов, которые затем выдавали за свои на публичных чтениях (декламациях), чтобы казаться интеллектуалами.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Do not delete this content: pause every editorial card about Russia,
-- Russian authors, Russian-language vocabulary, the USSR, or Soviet history.
-- The Lily selector already requires isActive = true, so the change takes
-- effect immediately for new facts while remaining fully reversible.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';

